contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // to: recipient address for migrateTo
    function run(address to) public payable {
        // record balance before
        uint256 beforeBalance = address(c).balance;

        // attempt migrateTo and record whether it reverted
        bool migratedReverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            migratedReverted = true;
        } else {
            migratedReverted = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: migrateTo either reverts and leaves balance unchanged, or succeeds and does not increase the contract balance
        assert(migratedReverted ? (afterBalance == beforeBalance) : (afterBalance <= beforeBalance));
    }

    receive() external payable {}
}

